import 'package:package_info_plus/package_info_plus.dart';

/// Runtime application version generated by Flutter from pubspec.yaml.
///
/// `pubspec.yaml` is the only maintained Mobile application-version source;
/// Android, iOS, About and API client identification all consume that package
/// metadata instead of repeating a literal in Dart code.
abstract final class AppVersion {
  static Future<String>? _current;

  static Future<String> current() => _current ??= _load();

  static Future<String> _load() async {
    final value = (await PackageInfo.fromPlatform()).version.trim();
    if (value.isEmpty) throw StateError('applicationVersionUnavailable');
    return value;
  }
}
